 ftp:{name:'FTP',title:'文件传输',brief:'控制连接协商命令，独立的数据连接传文件或目录列表。',meta:'TCP 21 / 独立数据连接',source:rfc(959),topics:[{title:'主动与被动模式',text:'主动模式由服务器发起数据连接；被动模式由客户端连接服务器给出的数据端口。经典主动模式服务端常用20端口，但不能把所有FTP数据连接都说成固定20端口。'},{title:'安全与相关协议',text:'原始FTP没有默认加密。FTPS是在FTP中增加TLS；SFTP是SSH的文件传输子系统，两者不能等同。'}]},
 imap:{name:'IMAP',title:'服务器邮箱同步',brief:'在服务器上管理邮箱、邮件和标记，使多个客户端同步查看邮件。',meta:'TCP 143 / TLS 993',source:rfc(9051),topics:[{title:'状态与选择',text:'客户端认证后选择邮箱，查看UID、标记与邮件内容。已读、删除等操作可以影响服务器上的状态，而不是仅仅下载一个文件。'},{title:'与SMTP配合',text:'IMAP负责访问邮件；提交新邮件通常由SMTP负责。IMAP的FETCH可以按需要读取正文或某些部分。'}]},
 pop3:{name:'POP3',title:'邮箱邮件获取',brief:'连接邮件服务器，列出并取回邮件；是否删除服务器副本取决于客户端操作。',meta:'TCP 110 / TLS 995',source:rfc(1939),topics:[{title:'三个阶段',text:'认证进入事务阶段，执行STAT/LIST/RETR等；DELE先标记删除，正常QUIT进入更新阶段后再处理删除。连接异常中断不等于已经提交删除。'},{title:'与IMAP的区别',text:'POP3侧重邮件获取，IMAP提供更丰富的服务器邮箱和状态管理。使用POP3不意味着每次下载都必须删除服务器邮件。'}]},
 websocket:{name:'WebSocket',title:'持续双向消息',brief:'在建立连接后，客户端和服务器都可以主动发送有边界的消息，适合实时交互。',meta:'常见 ws / wss',source:rfc(6455),topics:[{title:'握手与数据帧',text:'图中展示经典HTTP/1.1 Upgrade握手。成功后使用WebSocket帧，而不是每条消息都重新发起HTTP请求；其他HTTP版本有相应的连接建立机制。'},{title:'分帧与安全',text:'消息可以分为多个帧；Ping/Pong用于保活，Close用于关闭。客户端掩码不是加密，wss通常利用TLS保护。'}]},
 bgp:{name:'BGP',title:'自治系统间的路由控制',brief:'交换网络前缀与路径属性，按路由策略选择路径，是互联网路由控制的重要协议。',meta:'TCP 179 · 应用层控制协议',source:rfc(4271),topics:[{title:'路径与策略',text:'AS_PATH记录自治系统路径，可辅助防环；LOCAL_PREF、AS_PATH等属性参与选路。选出的路径受策略约束，不能简单等同于地理最近或链路最短。'},{title:'协议位置与用途',text:'BGP由TCP承载，实际TCP/IP协议栈中归入应用层；它的作用是为网络层提供路由控制信息。控制平面更新路由，数据平面按转发表转发用户分组。'}]},
 icmpv6:{name:'ICMPv6 / NDP',title:'IPv6诊断与邻居发现',brief:'ICMPv6提供IPv6差错和诊断；基于它的NDP完成邻居解析、路由器发现与可达性检测等。',meta:'IPv6 Next Header 58',source:rfc(4861),topics:[{title:'邻居与路由器',text:'NS/NA用于邻居解析等，RS/RA用于路由器发现和参数发布。RA可通告默认路由及前缀；地址自动配置还需要相应配置与SLAAC等机制。'},{title:'路径MTU',text:'IPv6路由器不执行分片。Packet Too Big反馈可帮助源端调整发送大小；过度阻断ICMPv6可能影响邻居发现和正常通信。'}]},
 ipsec:{name:'IPsec',title:'IP层的安全保护',brief:'一组保护IP通信的协议和机制，通过安全关联约定算法、密钥、序列号与保护方向。',meta:'ESP / AH / IKE',source:rfc(4301),topics:[{title:'ESP、AH与IKE',text:'ESP按协商算法提供保密性、完整性等保护；AH提供完整性与认证、不提供加密。IKE常用于协商密钥与安全关联，不能把它们都当成同一个报文格式。'},{title:'传输与隧道',text:'传输模式主要保护IP载荷；隧道模式封装原始IP分组并增加外层IP头，常见于VPN网关。图示为ESP隧道模式，增加的开销会影响有效MTU。'}]},
