add('tls','presentation','协议 / 表示功能','TLS 1.3 · 密钥怎样变成安全通信','协商密钥并认证身份，再保护应用数据的机密性与完整性。','sequence',['TLS客户端','TLS服务器'],[
 [0,1,'① ClientHello','客户端提供支持的版本、密码套件和密钥共享等参数，必要时还提供目标名称及应用协议协商信息。'],
 [1,0,'② ServerHello与参数','服务器选择参数并提供密钥共享信息。双方依据密钥交换结果和握手上下文派生后续密钥。'],
 [1,0,'③ 证书与Finished','服务器发送加密的握手内容，包括适用时的证书、签名与Finished；客户端核验名称、信任链及握手完整性。'],
 [0,1,'④ 客户端Finished','客户端证明自己掌握相应握手密钥。需要双向认证时，客户端也提交证书和签名。'],
 [0,1,'⑤ 受保护应用数据','使用对称加密与认证保护数据。证书公钥不是每次直接加密整个网页内容的工具。']
],[['http','HTTPS保护HTTP内容'],['tcp','常见TLS记录由TCP承载'],['quic','集成TLS 1.3握手而非TLS记录']],'TLS不替代TCP可靠传输，也不隐藏所有元数据。证书校验失败不能靠永久忽略验证解决。0-RTT是可选机制，存在重放方面的限制，图中不展开。','OSI表示层是功能示例；在TCP/IP四层视图列入应用层相关安全机制。');
add('encoding','presentation','编码标准','UTF-8 · 字符怎样变成字节','约定字符与字节的对应规则，使两端正确解释同一段文本。','flow',['字符“网”','Unicode码点','UTF-8字节','协议载荷','接收端解码'],[
 [0,1,'① 确定码点','字符“网”的Unicode码点为U+7F51。字符、码点和用户看到的字形并非在所有文字中都一一对应。'],
 [1,2,'② 编码为字节','U+7F51按UTF-8编码成E7 BD 91，共3字节；UTF-8对不同码点使用1至4字节。'],
 [2,3,'③ 放进消息体','HTTP等协议可以传这些字节。传输层只处理数据，不会自行猜出正确字符编码。'],
 [3,4,'④ 用相同规则解码','接收端按UTF-8解释字节恢复字符。用不一致编码解读可能乱码，收到正确的TCP字节也无法自动修复错误编码。']
],[['json','跨系统JSON交换通常用UTF-8'],['http','应用规定消息体编码']],'UTF-8是字符编码标准，不是传输协议。字节长度与字符串字符数不同；内容长度等字段需要按协议规定计数。');
add('json','presentation','数据格式','JSON · 对象怎样被另一种语言理解','序列化结构化数据；字段含义与验证规则仍由应用约定。','flow',['程序对象','JSON文本','UTF-8字节','传输消息体','解析与验证'],[
 [0,1,'① 序列化','把对象结构表示成JSON文本，如{"id":7,"ok":true}。JSON支持对象、数组、字符串、数值、布尔值和null。'],
 [1,2,'② 编码','跨系统交换JSON文本通常用UTF-8。格式正确不表示数字范围、日期格式和字段含义已约定一致。'],
 [2,3,'③ 协议承载','放进HTTP响应体或WebSocket消息。直接用TCP时仍需要长度等应用定界，JSON本身不能替TCP增加消息边界。'],
 [3,4,'④ 解析与验证','接收端先解析语法，再校验字段类型、必需字段和业务规则；反序列化不应意味着无条件信任输入。']
],[['encoding','UTF-8表达文本字节'],['http','Content-Type可声明application/json'],['websocket','JSON可作消息载荷'],['rpc','RPC系统可采用JSON序列化']],'JSON是数据格式，TLS是安全协议，HTTP是应用通信协议，三者负责不同问题。JSON没有原生日期类型，也不能把所有语言对象特性都无损表达。');
add('rpc','session','协议族 / 调用机制','RPC · 一次远程调用怎样关联响应','把本地调用转换成请求，并处理参数、关联标识、结果与失败。','sequence',['调用方','远程服务'],[
 [0,0,'① 参数序列化','调用代理将方法与参数编码，并生成请求关联ID。具体格式取决于RPC体系，图示不限定ONC RPC或gRPC。'],
 [0,1,'② 发送调用请求','请求通过相应应用协议和底层传输交付。并发调用需要区分各自响应，关联ID不等同于TCP序列号。'],
 [1,1,'③ 分派并执行','服务端解码参数、选择方法并执行业务。如果执行成功后响应丢失，客户端仍可能看到超时。'],
 [1,0,'④ 对应结果或错误','返回关联ID与结果/错误，客户端恢复调用结果。超时后重试必须结合幂等性、去重或状态查询。']
],[['json','一种可选序列化格式'],['http','部分RPC体系基于HTTP'],['tcp','部分RPC体系直接基于TCP'],['session','关联请求与持续交互状态']],'RPC是协议族与调用模式；ONC RPC、JSON-RPC、gRPC的格式和承载方式不同。可靠传输不能自动保证业务“恰好执行一次”。','这里用来说明OSI会话相关功能；实际TCP/IP中通常归入应用层。');
add('session','session','应用机制','应用会话 · 多次请求怎样识别同一个用户','在多个请求之间关联身份和交互状态，并管理过期与恢复。','sequence',['浏览器','应用服务器'],[
 [0,1,'① 提交登录凭证','通过受保护的连接提交身份凭证，服务器验证用户。登录过程与TCP三次握手是不同层次的问题。'],
 [1,0,'② 返回会话标识','示例采用服务器端会话与Cookie标识。会话标识需不可预测，并根据场景设置Secure、HttpOnly、SameSite等属性。'],
 [0,1,'③ 后续请求携带标识','请求携带Cookie，服务器将标识关联到会话状态。即使换了TCP连接，仍可识别这段登录交互。'],
 [1,1,'④ 校验与失效','服务器检查会话有效期和权限，注销或过期后使其失效。检查点和断点恢复还需要额外的应用设计。']
],[['http','Cookie帮助跨请求关联'],['tls','保护凭证与会话标识'],['rpc','任务与调用也需要状态关联']],'OSI会话层、网站登录Session、TCP连接不是同一概念。示例是服务器端会话；无状态令牌等方案有不同的验证和失效方式。','应用会话管理是一类机制，不是名为SESSION的统一网络协议。');
add('tcp','transport','协议','TCP · 丢失字节怎样被补回来','提供有序字节流，通过序号、确认和重传恢复丢失。','sequence',['发送端','接收端'],[
 [0,1,'① seq=1001，500字节','假定连接已建立，发送1001～1500的连续字节。TCP序列号按字节计数，不是简单的包编号。'],
 [1,0,'② ACK，ack=1501','接收端累计确认到1500，下一期待字节为1501。ACK标志位与确认号字段是不同概念。'],
 [0,1,'③ seq=1501丢失','发送1501～2000时发生丢失。图示消息带丢失标记，接收端未得到它，不应把箭头理解为已成功送达。'],
 [0,1,'④ 恢复并重传范围','发送端依据重传超时或其他丢失检测机制恢复丢失数据。图中简化为重传该连续范围，实际分段和恢复算法可不同。'],
 [1,0,'⑤ ACK，ack=2001','接收端补齐连续字节后推进累计确认，再按顺序交给应用。SYN、FIN各占一个序号，而普通纯ACK不占数据序号。']
],[['ipv4','由IP交付分组'],['http','HTTP/1.1、2常使用TCP'],['tls','安全保护由TLS等提供']],'发送约束由接收窗口rwnd、拥塞窗口cwnd及在途数据共同决定。TCP不保留应用消息边界，需应用定界；可靠传输仍可能因不可恢复故障向应用报错。','该图侧重已建连后的丢失恢复；握手与关闭可在TCP/UDP实验中查看。');
add('udp','transport','协议','UDP · 消息边界保留，送达不保证','用端口区分进程，以数据报形式提交独立消息。','sequence',['发送端','接收端'],[
 [0,1,'① 数据报1','每次提交形成独立UDP数据报；长度字段包括UDP头和数据，基本头8字节。'],
 [0,1,'② 数据报2丢失','IP路径可能丢失分组。UDP自身没有确认、超时补发或排序机制。'],
 [0,1,'③ 数据报3到达','数据报3可以正常到达，而2仍未送达；应用不能假定UDP会补齐中间数据。其他情况下路径或排队也可能造成乱序，需由业务机制识别。'],
 [1,1,'④ 应用决定恢复策略','应用按需求处理缺失、丢弃过时数据或自行恢复。UDP校验和用于差错检测，不等于可靠交付。']
],[['dns','传统DNS查询常用UDP'],['quic','QUIC在UDP上实现可靠安全传输'],['ipv4','IP负责尽力转发']],'四个16位字段为源端口、目的端口、长度、校验和。IPv4中的UDP零校验和表示未提供该校验；IPv6通常要求UDP校验和，少数特定隧道条件有例外。','图示是可能出现的丢失和乱序情形，不代表每次UDP通信都会丢包。');
add('quic','transport','协议','QUIC · UDP上怎样实现可靠多流','组合连接ID、多流、丢失恢复、拥塞控制和TLS 1.3安全握手。','sequence',['QUIC客户端','QUIC服务器'],[
 [0,1,'① Initial / ClientHello','QUIC通过UDP报文承载初始QUIC包和TLS握手数据。QUIC包号与流偏移分工不同：包用于传输恢复，流偏移用于重组数据。'],
 [1,0,'② 握手与身份验证','服务器回应并提供TLS握手信息；双方建立应用数据密钥。QUIC整合TLS握手，不是简单把传统TLS记录套进UDP。'],
 [0,1,'③ STREAM数据多路复用','同一连接内多个流独立交付有序字节，避免一个流缺失字节必然阻塞所有其他流。流内仍可能等待缺失数据。'],
 [1,0,'④ ACK与丢失恢复','QUIC确认收到的包范围，依据丢失检测重新发送需要的数据，新的发送使用新的包号。'],
 [0,1,'⑤ 路径变化与验证','在具备条件时，连接ID和路径验证帮助在地址变化后维持连接。拥塞与流控仍必不可少。']
],[['udp','UDP提供数据报承载'],['tls','TLS 1.3提供握手安全'],['http','HTTP/3使用QUIC']],'QUIC可靠性来自自己的恢复机制，而不是UDP。跨流交付减少传输层跨流队头阻塞，但并不消除流内顺序等待或所有应用依赖。');
add('ipv4','network','协议','IPv4 · 分组怎样跨越两个网络','按目的地址和最长前缀匹配选下一跳，提供尽力而为转发。','sequence',['主机A','路由器','主机B'],[
 [0,0,'① 目的网段判断','用目的地址与本地前缀判断是否在本地。跨网段时查路由选择网关，再解析下一跳MAC；不ARP远端主机的MAC。'],
 [0,1,'② 帧交给下一跳','源/目的IP为A/B，链路目的MAC为当前网关。以太网帧负责这一跳，IP地址用于跨网络寻址。'],
 [1,1,'③ 最长前缀匹配','路由器移除当前链路封装，查找路由并减少TTL，更新IPv4头校验和。TTL耗尽时不继续转发。'],
 [1,2,'④ 重新封装到下一跳','新链路使用新的源/目的MAC，普通无NAT转发中源/目的IP不变。需要时按MTU与DF等规则处理分片或差错。'],
 [2,2,'⑤ 目的端处理载荷','目的端根据IP协议号把载荷交给TCP、UDP、ICMP等；若存在分片，先按规则重组。']
],[['arp','解析IPv4下一跳MAC'],['ethernet','负责每条以太网链路'],['icmp','报告某些转发差错'],['ospf','路由协议提供路由信息']],'IPv4地址32位，基本头20字节。最长前缀匹配优先选择更具体路由；缺省路由只在没有更具体匹配时使用。NAT会改变地址，不能把普通路由的规则直接套给NAT。','图示无NAT，忽略额外隧道封装与策略路由。');
add('ipv6','network','协议','IPv6 · 转发与分片怎样改变','128位寻址，固定40字节基本头，依靠扩展头表达附加功能。','sequence',['IPv6主机A','IPv6路由器','IPv6主机B'],[
 [0,0,'① 路由与邻居解析','按路由表选下一跳，用NDP解析链路地址；IPv6不使用IPv4的ARP。'],
 [0,1,'② 发送IPv6分组','基本头包含源/目的地址、Next Header与Hop Limit等，不含IPv4式基本头校验和。'],
 [1,1,'③ 转发或Packet Too Big','路由器减少Hop Limit。如果分组超过出链路MTU，路由器不分片，而可通过ICMPv6反馈Packet Too Big。'],
 [1,2,'④ 逐跳到达目的端','符合MTU的分组继续转发。源端根据反馈减小发送大小，必要时由源端用分片扩展头分片。']
],[['icmpv6','邻居发现和MTU反馈'],['tcp','可靠传输与IP版本独立'],['ethernet','仍可由以太网承载']],'Next Header可以指向扩展头或上层协议，不能总当成直接的TCP/UDP标识。IPv6没有广播，使用单播、组播和任播；地址空间大不等于默认安全。','第三步描述分支，过大的分组不会同时被继续转发。');
add('icmp','network','协议','ICMP · ping与路由超时反馈','反馈部分网络差错，并提供回显等诊断消息。','sequence',['探测主机','路由器 / 目标'],[
 [0,1,'① 发出探测','ping常发送ICMP Echo Request；traceroute探测也可以使用UDP、TCP等，其TTL逐次增加。'],
 [1,1,'② 根据情形处理','目标可回答回显；路由器发现TTL耗尽、目标不可达等情形时，可按协议和策略生成相应差错消息。'],
 [1,0,'③ Echo / Time Exceeded','回显应答表示相应探测得到了回应；Time Exceeded等可帮助分析路径，差错报文常引用原始报文信息。'],
 [0,0,'④ 匹配并分析','工具关联探测与反馈，计算时间或记录节点。没有回应也可能是策略过滤或限速，不能单独证明主机离线。']
],[['ipv4','ICMPv4由IPv4承载'],['icmpv6','IPv6使用不同的ICMPv6'],['tcp','ping不测试TCP服务可用']],'ICMP使用类型、代码和校验和，没有TCP/UDP端口。它提供差错反馈而非给IP补上可靠重传；诊断结果应结合实际业务连接。');
add('ospf','network','协议','OSPF · 拓扑怎样变成路由表','在自治系统内部交换链路状态，再运行最短路径计算。','sequence',['路由器R1','邻居与区域路由器'],[
 [0,1,'① Hello发现邻居','交换Hello检查关键参数，建立适用的邻居/邻接关系。并非每一对可见邻居都会按同样方式形成完全邻接。'],
 [0,1,'② 同步链路状态数据库','通过数据库描述、请求和更新等报文同步LSA，使同一区域在收敛后具有一致的拓扑认识。'],
 [1,0,'③ LSA变化泛洪','链路变化触发相应状态信息传播。序列号、寿命与确认等机制帮助控制更新并保持数据库。'],
 [0,0,'④ SPF计算并生成路由','按链路代价运行最短路径计算，将符合规则的结果交给路由信息体系，数据转发再按已生成的表进行。']
],[['ipv4','OSPFv2直接由IP协议号89承载'],['bgp','域间策略路由用途不同']],'OSPF是控制平面，IP转发是数据平面。区域、骨干区域、DR/BDR及汇总等影响大型网络组织，图中仅展开单区域的核心逻辑。','图示聚合多台邻居，不逐个绘制全部LSA报文。');
add('icmpv6','network','协议族','ICMPv6 / NDP · IPv6怎样找到邻居','以组播与邻居报文完成链路地址解析，并支持路由器发现。','sequence',['IPv6主机A','邻居B / 路由器'],[
 [0,1,'① RS / RA发现路由器','主机可发Router Solicitation，路由器发Router Advertisement通告路由器生存时间、前缀和相关参数；RA也可主动周期发送。'],
 [0,1,'② NS查询目标邻居','需要解析链路地址时，向目标对应的请求节点组播地址发送Neighbor Solicitation，不使用IPv4式ARP广播。'],
 [1,0,'③ NA报告链路地址','目标通过Neighbor Advertisement提供信息；主机更新邻居缓存，随后可把帧交付下一跳。'],
 [0,0,'④ 维护邻居与路径','邻居可达性检测维护状态。Packet Too Big等其他ICMPv6类型另行承担路径MTU反馈，并非NS/NA完成所有诊断。']
],[['ipv6','IPv6通信的重要基础'],['arp','IPv4使用ARP，IPv6不用'],['ethernet','把邻居地址映射到链路地址']],'NDP不止“IPv6版ARP”，还承担路由器发现、重定向和可达性等功能。地址无状态自动配置与重复地址检测使用相关机制，但还需相应SLAAC规则。','将邻居与路由器合并为一个参与者，仅表示职责，实际设备可以不同。');
add('ipsec','network','协议族','IPsec · 原始IP包怎样穿过安全隧道','通过安全关联保护IP数据，隧道模式在外层再加IP封装。','flow',['协商安全关联','原始IP分组','ESP封装保护','外层IP转发','验证与解封装'],[
 [0,1,'① 先建立安全关联','常用IKE协商算法、密钥与参数。安全关联通常具有方向性，双向通信需要对应的保护状态。'],
 [1,2,'② 封装原始分组','在ESP隧道模式下，原始IP分组被作为内层数据保护；按协商算法进行加密、完整性与抗重放等处理。'],
 [2,3,'③ 增加外层IP头','外层源/目的地址指向隧道端点，公网路由器据此外层转发。加密载荷不妨碍它们读取外层路由地址。'],
 [3,4,'④ 校验与还原','对端按SPI定位安全关联，检查序号与完整性等，再解密、移除隧道封装并处理内层分组。']
],[['ipv4','保护IP层数据'],['ipv6','也支持IPv6'],['udp','NAT穿越可能使用UDP封装'],['tls','TLS保护应用通道，位置不同']],'ESP与AH是不同协议，AH不加密。隧道开销会降低可用载荷大小，路径MTU、NAT穿越和安全策略需要一起考虑。','图示ESP隧道模式；传输模式和实际协商报文不在这条流程中。');
add('ethernet','datalink','链路技术','以太网 · 交换机怎样把帧送到端口','按MAC地址在当前链路/广播域内交付帧。','sequence',['主机A','交换机','主机B'],[
 [0,1,'① 帧到达入端口','帧含目的MAC、源MAC、类型和载荷等。交换机读取源MAC，学习它位于哪个端口和对应VLAN。'],
 [1,1,'② 查目的MAC表','已知目的MAC时定向转发；未知单播和广播通常在相应VLAN内泛洪，不发回原入端口。'],
 [1,2,'③ 向目标端口转发','帧在同一二层域内交付。若要跨IP网段，通常需要路由功能，不能仅靠二层MAC学习解决。'],
 [2,2,'④ 校验并交给上层','接收接口检查帧并按EtherType区分载荷，例如IPv4、ARP或IPv6。FCS检测错误，不保证自动恢复丢失数据。']
],[['arp','解析IPv4下一跳MAC'],['vlan','划分二层广播域'],['stp','冗余交换链路需要防环'],['phy','信号由物理层承载']],'常见无VLAN以太网帧头14字节，FCS4字节；1500通常指以太网IP MTU而非完整帧长度。前导码、帧间隙等物理开销须按计算口径区分。','普通全双工交换式以太网不采用共享半双工网络的CSMA/CD碰撞恢复流程。');
add('wifi','datalink','无线链路技术','Wi-Fi · 无线共享介质怎样减少碰撞','以802.11帧在无线链路传输，用竞争与确认等机制处理共享介质。','sequence',['无线终端','接入点AP'],[
 [0,0,'① 监听与随机退避','竞争式访问中先侦听信道，满足条件后进行随机退避；空闲时倒数，忙时暂停，不能直接套用以太网碰撞检测。'],
 [0,1,'② 发送802.11数据帧','获得发送机会后发帧。图中省略关联、安全认证和可选RTS/CTS等过程。'],
 [1,0,'③ 链路ACK','很多单播传输使用确认。未及时收到确认可能触发链路重试，但广播/组播等不具有完全相同的确认流程。'],
 [1,1,'④ 桥接到其他链路','AP可将无线数据交给有线等链路。无线链路ACK与TCP端到端ACK是不同层次的确认。']
],[['ethernet','AP常桥接有线以太网'],['phy','无线编码与调制传送信号'],['tcp','端到端确认与链路ACK不同']],'802.11是包含MAC与PHY的标准体系。CSMA/CA主要用于理解竞争式接入，现代Wi-Fi还存在调度等机制；RTS/CTS不是所有帧的固定必经步骤。','示意常见竞争单播流程，不覆盖全部802.11接入机制与帧类型。');
add('arp','datalink','协议 / 层间边界','ARP · 为什么跨网段要找网关MAC','在本地IPv4链路上，把选定的下一跳IP解析为链路地址。','sequence',['主机A','本地链路 / 网关'],[
 [0,0,'① 查路由与ARP缓存','先由IPv4路由选下一跳。如果目的B不在本地网段，下一跳通常是网关；ARP目标不是远端B。'],
 [0,1,'② 广播ARP Request','请求在本地广播域内询问“谁拥有网关IP”。以太网目的MAC通常是ff:ff:ff:ff:ff:ff，ARP不是UDP消息。'],
 [1,0,'③ ARP Reply','拥有目标IP的接口通常单播回复其MAC。请求和回复可以携带发送方IP与MAC信息。'],
 [0,1,'④ 缓存并发送数据帧','A缓存映射，把目的IP仍为B的IP分组封装进目的MAC为网关的以太网帧。缓存会过期或更新。']
],[['ipv4','先选路由再解析下一跳'],['ethernet','ARP由链路帧直接承载'],['icmpv6','IPv6改用NDP']],'ARP位于网络寻址与链路交付的边界，TCP/IP教学常放在链路层。ARP广播不会由普通路由器转发到另一个广播域。','未包含代理ARP等特殊机制；不把ARP归为TCP/UDP应用。');
add('vlan','datalink','链路标记与机制','802.1Q VLAN · 一台交换机怎样分成多个域','通过VLAN成员关系和标签隔离二层广播域。','sequence',['VLAN10主机','交换机S1','交换机S2'],[
 [0,1,'① 接入口接收帧','典型Access口接收终端无标签帧，并按端口配置赋予VLAN10归属；其他配置情形需按设备规则判断。'],
 [1,2,'② Trunk携带VLAN标签','允许VLAN10通过的Trunk链路可使用802.1Q标签，包含优先级、DEI和VLAN ID等。原有帧增加4字节标签。'],
 [2,2,'③ 在VLAN内学习与转发','交换机按VLAN关联MAC表，广播通常只在对应VLAN内扩散；不能把所有端口一律当作一个广播域。'],
 [2,2,'④ 发往接入口或路由','发往对应Access口时通常移除标签。VLAN10到VLAN20通信还需要三层转发及允许的策略。']
],[['ethernet','标签属于以太网封装'],['stp','不同生成树模式影响VLAN拓扑'],['ipv4','跨VLAN通常需要三层路由']],'VLAN是二层隔离，IP子网是三层前缀，常一起规划但不是同一概念。Trunk的原生/无标签VLAN等行为依配置而变。','第四步画为S2本地处理，终端未单独绘制；不是VLAN20可以直接收到VLAN10广播。');
add('stp','datalink','桥接控制协议','STP / RSTP · 冗余链路怎样避免环路','交换控制信息，选择无环活动拓扑，避免广播和未知帧循环。','flow',['交换BPDU','选择根桥','计算端口角色','限制冗余转发','变化后重收敛'],[
 [0,1,'① 比较桥信息','交换机根据收到的BPDU比较桥ID等信息，传统STP选择最小桥ID为根桥。'],
 [1,2,'② 确定到根路径','非根桥选择到根的最佳路径及根端口；各网段比较路径信息选择指定端口。'],
 [2,3,'③ 阻断某些冗余路径','根据角色和状态限制普通用户帧转发，使活动拓扑无环，同时保留物理冗余。'],
 [3,4,'④ 处理链路变化','故障或拓扑变化时重新计算并收敛，可能启用先前未转发的端口；RSTP利用更快的协商等机制改善收敛。']
],[['ethernet','保护二层交换拓扑'],['vlan','生成树和VLAN拓扑需共同规划']],'二层帧可能没有IP头，不能靠TTL防止交换环路。MAC漂移、广播风暴等可能由环路引起；STP不是对每个用户分组重新计算最短路径。','图是算法处理流程，未描绘某个特定厂商的全部端口状态。');
add('ppp','datalink','协议族','PPP · 点到点链路先协商再传数据','为点到点连接提供封装、链路协商和多网络协议支持。','sequence',['端点A','端点B'],[
 [0,1,'① LCP协商链路','双方交换配置请求与确认/否认，商定链路选项。链路建立和IP地址配置是不同阶段。'],
 [1,0,'② 可选认证','按协商执行认证，例如PAP或CHAP。认证服务本身不意味着后续所有数据已经加密。'],
 [0,1,'③ NCP协商网络层','使用相应NCP为网络层协议配置参数，例如IPCP用于IPv4相关参数，IPv6CP用于IPv6相关链路参数。'],
 [0,1,'④ 封装网络层分组','PPP协议字段标识载荷类型，帧校验检测错误。关闭时使用相应终止流程。']
],[['ipv4','IPCP及IPv4承载'],['ipv6','IPv6CP及IPv6承载'],['phy','依赖底层链路传输']],'PPP没有以太网式多点MAC寻址需求。PPPoE在以太网中承载PPP，额外封装开销可能使常见IP MTU从1500减到1492，具体配置可能支持其他大小。');
add('phy','physical','物理标准 / 功能','PHY · 位怎样变成可接收的信号','编码、调制与同步使介质能够承载数字信息。','flow',['上层比特','编码与成帧边界','调制 / 电光信号','接收与同步','还原比特'],[
 [0,1,'① 接收比特序列','物理层接收相应链路接口提供的数字信息，具体接口与编码粒度取决于标准。'],
 [1,2,'② 编码与发射','线路编码、扰码或调制等按标准把信息变成适于介质传播的信号，不同以太网和无线PHY使用不同方案。'],
 [2,3,'③ 经介质到达接收端','电信号、光信号或电磁波传播时受衰减、噪声和干扰影响。链路速率不是信号的传播速度。'],
 [3,4,'④ 同步与解码','接收端恢复时钟/符号并还原比特，无法纠正的错误可能交给后续检测机制发现。自动协商、FEC等是否存在依标准而定。']
],[['medium','物理介质决定传输条件'],['ethernet','以太网包含多种PHY'],['wifi','无线使用相应PHY']],'物理层不是一个统一报文协议；1000BASE-T、10GBASE-SR和802.11的PHY是不同技术。比特率和波特率需结合每符号承载信息及编码开销理解。','处理流程只表示共同功能，不声称每种PHY都具备所有画出的具体实现。');
add('medium','physical','介质与物理概念','传输介质 · 距离、速率和时延怎样配合','双绞线、光纤与无线提供传播环境，影响距离、损耗与容量。','flow',['发送1500字节','链路送出比特','传播1000公里','接收信号','链路与上层处理'],[
 [0,1,'① 发送时延 L / R','1500字节为12000比特，100Mb/s链路送出它们约需0.12ms。使用字节与比特时必须换算。'],
 [1,2,'② 传播时延 d / v','若距离1000km、传播速度2×10⁸m/s，单程传播约5ms。提高比特率不直接缩短同一介质上的传播距离。'],
 [2,3,'③ 信号与损耗','接收端面对衰减、噪声与干扰；光纤也存在色散和损耗，不能概括成没有距离限制。'],
 [3,4,'④ 其他时延叠加','设备处理、排队、协议握手与重传还会增加端到端延迟。这里的0.12+5ms只是指定假设下的简化结果。']
],[['phy','PHY把信息映射到介质信号'],['ethernet','以太网可运行于铜缆和光纤'],['wifi','无线共享射频介质']],'带宽可指频谱宽度或口语中的链路容量，需说明单位；吞吐量是实际传输速率。时延、容量、误码率与传播距离是不同指标。','媒介不是协议。此图是发送与传播的概念流程，二者实际在时间上可能重叠。');

export const PROTOCOL_LAYER_KEYS={osi:['application','presentation','session','transport','network','datalink','physical'],tcpip:['tcp-application','tcp-transport','internet','interface']};
export function protocolIds(model,layer){const groups={ 'tcp-application':['application','presentation','session'],'tcp-transport':['transport'],internet:['network'],interface:['datalink','physical']};return Object.keys(ATLAS).filter(id=>(groups[layer]||[layer]).includes(ATLAS[id].layer));}
